CREATE OR ALTER PROCEDURE dbo.CreateExternalDataSources
    @storageAccountUrl NVARCHAR(200)
AS
BEGIN
    DECLARE @sql NVARCHAR(MAX);

    IF NOT EXISTS (SELECT * FROM sys.database_scoped_credentials WHERE name = 'my_credentials')
    BEGIN
        -- It helps synapse to authenticate the ADLS Gen2
        CREATE DATABASE SCOPED CREDENTIAL my_credentials
        WITH IDENTITY = 'Managed Identity';
    END

    IF EXISTS (SELECT * FROM sys.external_data_sources WHERE name = 'silver_layer')
        DROP EXTERNAL DATA SOURCE silver_layer;

    -- external data source is the original location of our data
    SET @sql = N'CREATE EXTERNAL DATA SOURCE silver_layer
    WITH (
        LOCATION = ''' + @storageAccountUrl + '/silver/'',
        CREDENTIAL = my_credentials
    );';
    EXEC sp_executesql @sql;

    IF EXISTS (SELECT * FROM sys.external_data_sources WHERE name = 'gold_layer')
        DROP EXTERNAL DATA SOURCE gold_layer;

    SET @sql = N'CREATE EXTERNAL DATA SOURCE gold_layer
    WITH (
        LOCATION = ''' + @storageAccountUrl + '/gold/'',
        CREDENTIAL = my_credentials
    );';
    EXEC sp_executesql @sql;

    IF NOT EXISTS (SELECT * FROM sys.external_file_formats WHERE name = 'parquetFormat')
    BEGIN
        -- File format in which data is stored
        CREATE EXTERNAL FILE FORMAT parquetFormat
        WITH (FORMAT_TYPE = PARQUET);
    END
END
